  python3 tools/logprob_diff.py save NAME      # capture the current server as NAME (lp0 = baseline)
  python3 tools/logprob_diff.py check NAME     # current server vs NAME: max/mean |"    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "save":
        name = sys.argv[2]
        path = D / f"{name}.json"
        path.write_text(json.dumps(collect(), indent=2) + "\n")
        print(f"  saved {path}")
    elif cmd == "check":
        name = sys.argv[2]
        reference = json.loads((D / f"{name}.json").read_text())
        current = collect(cached=reference)
        report = stats(reference, current)
        print_report(f"{name} vs current", report)
    elif cmd == "compare":
        a, b = sys.argv[2], sys.argv[3]
        ra = json.loads((D / f"{a}.json").read_text())
        rb = json.loads((D / f"{b}.json").read_text())
        print_report(f"{b} vs {a}", stats(ra, rb))
        print_report(f"{a} vs {b}", stats(rb, ra))
    else:
        print(f"  unknown command {cmd}")
        sys.exit(1)


if __name__ == "__main__":
    main()


